"""
Generate CONFIG.md from the Pydantic settings models, so the reference can
never drift from the code.

    python scripts/gen_config_docs.py            # rewrite CONFIG.md
    python scripts/gen_config_docs.py --check    # exit 1 if CONFIG.md is stale (CI)
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path
from typing import Any, get_args

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from config.settings import ENV_MAPPING, Settings  # noqa: E402

HEADER = """# SpeechShield configuration reference

<!-- Generated by scripts/gen_config_docs.py — edit the Field descriptions in
     config/settings.py, not this file. -->

Settings are resolved in this order (highest wins):

1. Command-line flags (`python main.py --help`)
2. Environment variables (`SPEECHSHIELD_*`, see the *Env var* column)
3. `config/<env>.yaml` — `dev`, `test` or `prod`, chosen by `SPEECHSHIELD_ENV`
4. `config/default.yaml`
5. The defaults below

Every value is validated on start-up; an invalid value stops the program
with a message naming the field.
"""


def _type(annotation: Any) -> str:
    args = get_args(annotation)
    if args and all(isinstance(a, str) for a in args):
        return " \\| ".join(f"`{a}`" for a in args)
    name = getattr(annotation, "__name__", str(annotation))
    if args:
        name = " \\| ".join(getattr(a, "__name__", str(a)).replace("NoneType", "null") for a in args)
    return name


def _range(field: Any) -> str:
    bits = []
    for m in field.metadata:
        for attr, sym in (("ge", "≥"), ("gt", ">"), ("le", "≤"), ("lt", "<")):
            if getattr(m, attr, None) is not None:
                bits.append(f"{sym} {getattr(m, attr)}")
    return ", ".join(bits)


def render() -> str:
    env_for = {path: var for var, path in ENV_MAPPING.items()}
    out = [HEADER]
    for section, sfield in Settings.model_fields.items():
        model = sfield.annotation
        if not hasattr(model, "model_fields"):
            continue
        out.append(f"\n## `{section}`\n")
        if model.__doc__:
            out.append(" ".join(model.__doc__.split()) + "\n")
        out.append("| Key | Type | Default | Range | Env var | Description |")
        out.append("|---|---|---|---|---|---|")
        for key, f in model.model_fields.items():
            default = f.default if f.default is not None else "null"
            env = env_for.get((section, key), "")
            desc = (f.description or "").replace("|", "\\|")
            out.append(f"| `{key}` | {_type(f.annotation)} | `{default}` | {_range(f)} | {f'`{env}`' if env else ''} | {desc} |")
    top = [k for k, f in Settings.model_fields.items() if not hasattr(f.annotation, "model_fields")]
    out.append("\n## Top level\n")
    out.append("| Key | Default | Env var |")
    out.append("|---|---|---|")
    for k in top:
        out.append(f"| `{k}` | `{Settings.model_fields[k].default}` | `{env_for.get((k,), '')}` |")
    return "\n".join(out) + "\n"


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--check", action="store_true")
    args = ap.parse_args()
    target = ROOT / "CONFIG.md"
    text = render()
    if args.check:
        if not target.exists() or target.read_text(encoding="utf-8") != text:
            sys.exit("CONFIG.md is out of date — run: python scripts/gen_config_docs.py")
        return
    target.write_text(text, encoding="utf-8")
    print(f"wrote {target}")


if __name__ == "__main__":
    main()
